```sol
heapInit start end =
  let lo = alignUp (Addr.toWord start)
  and hi = Word.and (Addr.toWord end) (Word.not (w 15))
  in
  case i hi <= i lo of
    True -> error "Builtin: heap too small"
  | False ->
    case i (Word.sub hi lo) < 96 of
      True -> error "Builtin: heap too small"
    | False ->
      let h = Block.at (Addr.fromWord lo)
      in
      zeroWords (Block.addr h) 8;
      Block.setSize h (Word.sub hi lo);
      Heap.setHead (st Unit) h;
      Heap.setLow (st Unit) lo;
      Heap.setHigh (st Unit) hi
```

