  slot = Esp.jobNew Unit;
  _ = Sys.irqBind slot self;
  r = (case start slot of
      0 -> m = receive self;
      _ -> m = "error\tthe job queue is full";
      Esp.jobResult slot
    );
  _ = send boss (Ok r);
  Unit.
```

