// Using MAP_EXCL with MAP_FIXED to guarantee the address hint
void *addr = mmap(NULL, size, PROT_READ | PROT_WRITE,
                  MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED | MAP_EXCL,
                  -1, offset);
if (addr == MAP_FAILED) {
    // Address reservation failed
    return NULL;
}
```

