fn update(ctx: Context, state: State) -> (State, Scene2D, Subscriptions) {
    let new_state = state | with_effect {
        subscribe_to_stream { telemetry } -> telemetry
    };
    (new_state, Scene2D { ... }, { telemetry: telemetry })
}
```

