import std/os;

main = () ->
    write "Hello from POSIX";
    exit 0;

// Example of a QOS-portable program (fpr build --profile=qos-portable)
# This code runs as a QOS app image
import qos_hal_t;

main = () ->
    qos_hal_t.tty.write "Hello from QOS";
    exit 0;
```

