  address = "127.0.0.1";
  port = 8080;
  title = "Live Sol";
  store = "live.kvlog";
  watch = ["main.sol"];
  rebuild = [
    (fn () -> {
      _ = P.run "solc --standard-json < main.sol > output.sol";
      _ = A.sendSure self reg (0, Reload);
    })
  ];
  restart = Nil;
};

let _ = live.start cfg;
```

