actor conn(id: int) {
  buffer = new Buffer();
  stats = new Stats();
  register.register(self, id);

  // Parse frames and push delta independently
  frame = readSocket();
  if (frame.valid) {
    parse(frame);
    register.broadcastDelta(id, frame.delta);
  }
}
```

