@external
fn unsupported_op() -> Result {
    // Attempting to use a feature not in the host's instruction set
    // or not provided by the runtime's value behavior.
    // The QOS runtime would detect this and return an explicit error.
    error UnsupportedOperation("Missing host service or instruction")
}
```

