A client actor initializes a UART state machine with a default buffer capacity, sends data using `UWrite` requests which are queued in the `txq` field until the buffer is full or the device acknowledges, and monitors the `lsrDR` (Data Ready) bit of the Line Status Register to detect incoming data.

```fpr
actor main = loop me (St 0 0 4096 "" "" 0 0 0);

loop me st =
  m = receive me;
  case m of
    (from, UWrite "HELLO") -> 
      st' = st & (St st.dev st.owner (st.cap - 5) "HELLO" st.rxs st.sub st.flarmed);
      send me (from, UWrite "HELLO");
      send me (from, UGet);
    (from, UGet) -> 
      let rxs = st.rxs in
      if lsrDR (receive (from, UGet)) then
        send me (from, UOkI (length rxs))
      else
        send me (from, UOk 0);
    _ -> send me (from, UOk 0);
  | irq -> onIrq me st irq;
```

