v2mul a b = V2 ax ay = a; V2 bx by = b; V2 (ax * bx) (ay * by).

Vec2 = Struct {
  (+) = fn a b -> v2add a b,
  (*) = fn a b -> v2mul a b
}.

> p = V2 1 2;
  q = V2 10 20;
  print "p + q = {p + q}";
