    // Some memory read
    x = Mem.read(0x1000)
    // Some I/O write
    Mem.write(0x2000, 1)
}

// Correct: Explicit fence ensures ordering
func foo() {
    x = Mem.read(0x1000)
    Mem.fence
    Mem.write(0x2000, 1)
}
```

