  (mw, mh, n) = msum row kids;
  g = gapOf a;
  gaps = case n > 1 of True -> g * (n - 1) | False -> 0;
  avail = case row of True -> w - 2 * p | False -> h - 2 * p;
  used = case row of True -> mw + gaps | False -> mh + gaps;
  ng = countGrow kids;
  case ng > 0 of
    True -> idiv (avail - used) ng
  | False -> 0.

countGrow Nil = 0.
countGrow (k :: r) =
  n = countGrow r;
  case grows (attrsOf k) of True -> n + 1 | False -> n.

idiv a b | b == 0 = 0.
idiv a b | a < 0 = 0.
idiv a b = a / b.
```
What is the result of `grownSlack` when the input list `kids` is empty, and why does the function handle this case specifically?

answer:
The `grownSlack` function calculates the available space along an axis by subtracting the total width and height of the children (including gaps between them) from the container's inner dimensions, adjusted for padding. It then divides this remaining space evenly among all `Grow` children if any exist. If no children are marked to grow, the result is zero.

```fprisc
grownSlack row a kids w h p =
  (mw, mh, n) = msum row kids;
  g = gapOf a;
  gaps = case n > 1 of True -> g * (n - 1) | False -> 0;
  avail = case row of True -> w - 2 * p | False -> h - 2 * p;
  used = case row of True -> mw + gaps | False -> mh + gaps;
  ng = countGrow kids;
  case ng > 0 of
    True -> idiv (avail - used) ng
  | False -> 0.
```

