```fpr
fn safe_eq(s1: String, s2: String) -> Bool {
    len1 = len(s1);
    len2 = len(s2);
    if len1 != len2 then return False;
    i = 0;
    while i < len1 do {
        if charAt(s1, i) != charAt(s2, i) then return False;
        i = i + 1;
    };
    return True;
}
```

